import time
from concurrent.futures import ThreadPoolExecutor, wait, ALL_COMPLETED

def search(query: str, deadline_ms: int = 250):
    start = time.monotonic()
    def time_left_ms():
        return deadline_ms - int((time.monotonic() - start) * 1000)

    # 1. Fast path: usually good enough, single-digit ms.
    hit = cache_get(query)
    if hit and hit.fresh_enough(max_age_s=60):
        return result(items=hit.items, degraded=False, source="cache")

    # 2. Slow path: fan-out bounded by remaining budget.
    # Trade-off: smaller budget = lower coverage but bounded p99.
    budget = time_left_ms()
    if budget <= 20:
        return result(items=hit.items if hit else [], degraded=True, source="stale")

    shards = route_shards(query, max_shards=8 if budget > 150 else 3)
    with ThreadPoolExecutor(max_workers=len(shards)) as pool:
        futs = [pool.submit(query_shard, s, query) for s in shards]
        done, _ = wait(futs, timeout=budget / 1000.0, return_when=ALL_COMPLETED)
        got = [f.result() for f in done if not f.exception()]

    if not got:
        return result(items=hit.items if hit else [], degraded=True, source="stale")

    # 3. Spend what is left on accuracy, not more.
    remaining = time_left_ms()
    items = merge(got)
    if remaining > 40:
        items = rerank(items, top_k=50 if remaining < 100 else 200)
        degraded = len(done) != len(shards)  # partial coverage => flag it
    else:
        degraded = True  # no time to verify => say so

    return result(items=items, degraded=degraded, source="origin")
